from lib import *
L = lambda *a, **k: lesson(8, "A0", *a, **k)
A = "adjective"
L(1, "Червоний, синій, зелений", "Назвати основні кольори й спитати, якого кольору річ.",
 "What colour is it? — «Якого це кольору?». Відповідь: It's red. Колір стоїть перед річчю: a red car. У Британії пишуть colour, в Америці — color.",
 [W("colour", "/ˈkʌlə/", "noun", "колір", "What colour is it?", "Якого це кольору?"),
  W("red", "/red/", A, "червоний", "It's a red car.", "Це червона машина."),
  W("blue", "/bluː/", A, "синій, блакитний", "My bag is blue.", "Моя сумка синя."),
  W("green", "/ɡriːn/", A, "зелений", "It's a green door.", "Це зелені двері."),
  W("yellow", "/ˈjeləʊ/", A, "жовтий", "It's a yellow bus.", "Це жовтий автобус.")],
 [li("Let's meet on Sunday.", "Повторимо. Ви згодні. Що відповісти?", ["Sure!", "Sorry.", "It's Sunday."], "Sure! — «Авжеж!»"),
  mt([("red", "червоний"), ("blue", "синій"), ("green", "зелений"), ("yellow", "жовтий")], "Чотири основні кольори."),
  mt([("black", "чорний"), ("white", "білий"), ("colour", "колір"), ("new", "новий")], "Black і white ви знаєте з кафе."),
  liu("What colour is it?", "Прослухайте. Що вас питають?", ["Якого це кольору?", "Що це?", "Скільки це коштує?"], "What colour — якого кольору."),
  liu("It's a yellow bus.", "Прослухайте. Якого кольору автобус?", ["Жовтого", "Зеленого", "Червоного"], "Yellow — жовтий."),
  mc("Як сказати «червона машина»?", ["a red car", "a car red", "red a car"], "Колір стоїть перед річчю."),
  fb("My car is ___.", ["blue", "colour", "what"], "My car is blue — моя машина синя."),
  bs("Якого це кольору?", ["What", "colour", "is", "it"], ["red", "are"], "What colour is it?"),
  tr("Це зелені двері.", ["It's a green door", "It is a green door", "This is a green door"], "It's a green door. Door — однина."),
  li("What colour is your bag?", "Ваша сумка чорна. Що відповісти?", ["It's black.", "It's a bag.", "I'm black bag."], "It's black.")])
L(2, "Ще кольори", "Назвати решту кольорів і відтінки: темний і світлий.",
 "Dark — темний, light — світлий. Їх ставлять перед кольором: dark blue, light green.",
 [W("orange", "/ˈɒrɪndʒ/", A, "помаранчевий", "My bag is orange.", "Моя сумка помаранчева."),
  W("pink", "/pɪŋk/", A, "рожевий", "It's a pink dress.", "Це рожева сукня."),
  W("brown", "/braʊn/", A, "коричневий", "Brown shoes.", "Коричневе взуття."),
  W("grey", "/ɡreɪ/", A, "сірий", "It's a grey car.", "Це сіра машина."),
  W("purple", "/ˈpɜːpl/", A, "фіолетовий", "It's purple.", "Воно фіолетове."),
  W("dark", "/dɑːk/", A, "темний", "Dark blue.", "Темно-синій."),
  W("light", "/laɪt/", A, "світлий", "Light green.", "Світло-зелений.")],
 [fb("It's a ___ bus.", ["yellow", "colour", "is"], "A yellow bus — жовтий автобус.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("orange", "помаранчевий"), ("pink", "рожевий"), ("brown", "коричневий"), ("grey", "сірий"), ("purple", "фіолетовий")], "Ще п'ять кольорів."),
  mt([("dark", "темний"), ("light", "світлий"), ("big", "великий"), ("small", "малий")], "Dark і light — про відтінок."),
  liu("dark blue", "Прослухайте. Який це колір?", ["Темно-синій", "Світло-синій", "Темно-зелений"], "Dark — темний."),
  liu("My shoes are brown.", "Прослухайте. Якого кольору взуття?", ["Коричневого", "Сірого", "Чорного"], "Brown — коричневий."),
  mc("Як сказати «світло-зелений»?", ["light green", "green light", "dark green"], "Спочатку light, потім колір."),
  mcu("Червоний і білий разом дають…", ["pink", "purple", "brown"], "Red + white = pink."),
  fb("It's a ___ grey car.", ["dark", "very", "colour"], "Dark grey — темно-сірий."),
  tr("темно-синій", ["dark blue"], "Dark blue."),
  li("What colour are your shoes?", "Ваше взуття сіре. Що відповісти?", ["They're grey.", "It's a shoes.", "I'm grey."], "Про кілька речей: They're grey — «вони сірі».")])
L(3, "Мій улюблений колір", "Сказати, що вам подобається, а що ні.",
 "I like… — «мені подобається…». I don't like… — «мені не подобається…». I love… — сильніше: «я обожнюю…». My favourite colour is blue — «мій улюблений колір синій».",
 [W("like", "/laɪk/", "verb", "подобатися, любити", "I like blue.", "Мені подобається синій."),
  W("don't like", "/ˌdəʊnt ˈlaɪk/", "phrase", "не подобається", "I don't like grey.", "Мені не подобається сірий."),
  W("love", "/lʌv/", "verb", "любити, обожнювати", "I love red.", "Я обожнюю червоний."),
  W("favourite", "/ˈfeɪvərɪt/", A, "улюблений", "My favourite colour is green.", "Мій улюблений колір зелений."),
  W("sky", "/skaɪ/", "noun", "небо", "The sky is blue.", "Небо синє."),
  W("sun", "/sʌn/", "noun", "сонце", "The sun is yellow.", "Сонце жовте."),
  W("tree", "/triː/", "noun", "дерево", "The tree is green.", "Дерево зелене."),
  W("flower", "/ˈflaʊə/", "noun", "квітка", "It's a red flower.", "Це червона квітка.")],
 [mc("Повторимо. Як сказати «темно-зелений»?", ["dark green", "light green", "green dark"], "Dark green."),
  mt([("like", "подобатися"), ("love", "обожнювати"), ("favourite", "улюблений"), ("don't like", "не подобається")], "Like — подобається, love — сильніше."),
  mt([("sky", "небо"), ("sun", "сонце"), ("tree", "дерево"), ("flower", "квітка")], "Sun (сонце) і son (син) звучать однаково."),
  liu("My favourite colour is purple.", "Прослухайте. Який улюблений колір людини?", ["Фіолетовий", "Рожевий", "Синій"], "Purple — фіолетовий."),
  fb("I ___ like grey.", ["don't", "not", "no"], "«Не подобається» — I don't like."),
  fb("The sky is ___.", ["blue", "green", "brown"], "Небо синє — blue."),
  liu("I love flowers.", "Прослухайте. Що каже людина?", ["Я обожнюю квіти", "Мені не подобаються квіти", "У мене є квіти"], "I love — я обожнюю."),
  bs("Мій улюблений колір синій.", ["My", "favourite", "colour", "is", "blue"], ["like", "the"], "My favourite colour is blue."),
  tr("Мені подобається зелений.", ["I like green"], "I like green."),
  li("What's your favourite colour?", "Ваш улюблений колір червоний. Що відповісти?", ["It's red.", "I don't like red.", "It's a colour."], "It's red або My favourite colour is red.")])
L(4, "Як він виглядає?", "Описати людину: колір очей, волосся, одяг.",
 "I have, але he has і she has: She has blue eyes. Hair — завжди однина: long hair. Порядок слів: довжина, потім колір — long brown hair.",
 [W("has", "/hæz/", "verb", "має (з he, she, it)", "She has blue eyes.", "У неї сині очі."),
  W("eyes", "/aɪz/", "noun", "очі", "He has brown eyes.", "У нього карі очі."),
  W("hair", "/heə/", "noun", "волосся", "She has long hair.", "У неї довге волосся."),
  W("long", "/lɒŋ/", A, "довгий", "Long hair.", "Довге волосся."),
  W("short", "/ʃɔːt/", A, "короткий", "Short hair.", "Коротке волосся."),
  W("dress", "/dres/", "noun", "сукня", "A red dress.", "Червона сукня."),
  W("jacket", "/ˈdʒækɪt/", "noun", "куртка, піджак", "A black jacket.", "Чорна куртка.")],
 [fb("I ___ like pink.", ["don't", "not", "am"], "I don't like pink.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("eyes", "очі"), ("hair", "волосся"), ("long", "довгий"), ("short", "короткий")], "Long і short — протилежні слова."),
  mt([("dress", "сукня"), ("jacket", "куртка"), ("shoes", "взуття"), ("bag", "сумка")], "Одяг і речі."),
  fb("She ___ green eyes.", ["has", "have", "is"], "З he і she — has."),
  fb("I ___ short hair.", ["have", "has", "am"], "З I — have."),
  liu("He has short dark hair.", "Прослухайте. Яке в нього волосся?", ["Коротке темне", "Довге темне", "Коротке світле"], "Short — коротке, dark — темне."),
  mc("Як сказати «довге каштанове волосся»?", ["long brown hair", "brown long hair", "long brown hairs"], "Спочатку довжина, потім колір. Hair — без -s."),
  bs("У неї сині очі.", ["She", "has", "blue", "eyes"], ["have", "is"], "She has blue eyes."),
  tr("У нього чорна куртка.", ["He has a black jacket"], "He has a black jacket."),
  li("Who is Anna?", "Анна — жінка в червоній сукні з довгим волоссям. Як її описати?", ["She has long hair and a red dress.", "She have long hair and red dress.", "He has long hair and a red dress."], "She has… — про жінку, і has, а не have.")])
L(5, "Є таке в синьому?", "Попросити в магазині інший колір або розмір.",
 "Do you have this in blue? — «Є таке в синьому?». Щоб не повторювати назву речі, кажуть one: the red one — «червоний». Which one? — «Котрий?». Якщо берете: I'll take it.",
 [W("which", "/wɪtʃ/", "pronoun", "котрий, який із", "Which one?", "Котрий?"),
  W("this one", "/ˈðɪs wʌn/", "phrase", "ось цей", "This one, please.", "Ось цей, будь ласка."),
  W("that one", "/ˈðæt wʌn/", "phrase", "он той", "That one, please.", "Он той, будь ласка."),
  W("size", "/saɪz/", "noun", "розмір", "What size?", "Який розмір?"),
  W("medium", "/ˈmiːdiəm/", A, "середній", "Medium, please.", "Середній, будь ласка."),
  W("I'll take it", "/aɪl ˈteɪk ɪt/", "phrase", "я це беру", "Great, I'll take it.", "Чудово, я це беру.")],
 [fb("She ___ long hair.", ["has", "have", "is"], "She has.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("which", "котрий"), ("this one", "ось цей"), ("that one", "он той"), ("size", "розмір")], "One замінює назву речі."),
  mt([("small", "малий"), ("medium", "середній"), ("large", "великий"), ("I'll take it", "я це беру")], "Три розміри: small, medium, large."),
  liu("Do you have this in blue?", "Прослухайте. Що питає покупець?", ["Чи є таке в синьому", "Чи є таке більше", "Скільки коштує синє"], "In blue — у синьому кольорі."),
  liu("What size?", "Прослухайте. Що питає продавець?", ["Який розмір?", "Який колір?", "Яка ціна?"], "Size — розмір."),
  fb("Do you have this ___ black?", ["in", "on", "at"], "У кольорі — in black."),
  mc("Продавець показує дві куртки. Ви хочете червону. Що сказати?", ["The red one, please.", "The red, one please.", "One red the, please."], "The red one — «червону»."),
  bs("Чудово, я це беру.", ["Great", "I'll", "take", "it"], ["have", "one"], "Great, I'll take it."),
  tr("Ось цей, будь ласка.", ["This one, please"], "This one, please."),
  li("Which one would you like?", "Вас питають, котрий ви хочете. Ви хочете зелений. Що відповісти?", ["The green one, please.", "Yes, I like.", "It's green colour."], "The green one, please.")])
L(6, "Повторення: кольори навколо", "Назвати колір будь-якої речі, описати людину й попросити потрібний колір у магазині.",
 "Нових слів немає. Повторюємо кольори, dark і light, I like і I don't like, he has і she has, the red one.",
 [],
 [li("What colour is the sky?", "Що відповісти?", ["It's blue.", "It's green.", "It's a sky."], "The sky is blue."),
  mc("Як сказати «світло-сірий»?", ["light grey", "grey light", "dark grey"], "Light grey."),
  fb("He ___ brown eyes and short hair.", ["has", "have", "is"], "He has."),
  tr("Мій улюблений колір зелений.", ["My favourite colour is green"], "My favourite colour is green."),
  liu("She has long dark hair and a yellow dress.", "Прослухайте. Як виглядає жінка?", ["Довге темне волосся, жовта сукня", "Коротке темне волосся, жовта сукня", "Довге світле волосся, зелена сукня"], "Long dark hair, a yellow dress."),
  bs("Мені не подобається рожевий.", ["I", "don't", "like", "pink"], ["not", "love"], "I don't like pink."),
  fb("Do you have this ___ medium?", ["in", "on", "at"], "In medium — у середньому розмірі."),
  li("Which one would you like?", "Ви хочете чорну. Що відповісти?", ["The black one, please.", "Black is one.", "I'm black one."], "The black one, please."),
  liu("It's forty pounds. — OK, I'll take it.", "Прослухайте. Що вирішив покупець?", ["Купити", "Не купувати", "Попросити інший колір"], "I'll take it — я це беру."),
  li("What colour is your car?", "У вас темно-синя машина. Що відповісти?", ["It's dark blue.", "It's blue dark.", "I have dark."], "It's dark blue.")],
 review=True)
